<section id="stockBranches" class="stock-branches" hidden>
 <details id="branchDetails" hidden><summary><?= stock_icon('branch') ?><span>Sucursales</span><?= stock_icon('chevron') ?></summary>
  <div class="branch-toolbar"><label class="branch-search"><?= stock_icon('search') ?><input id="branchSearch" type="search" placeholder="Buscar sucursal o dirección" aria-label="Buscar sucursal"></label><button id="newBranch" class="library-primary stock-icon" type="button" aria-label="Agregar sucursal" title="Agregar sucursal"><?= stock_icon('plus') ?></button></div>
  <div id="branchList" class="branch-list"></div>
 </details>
 <div class="branch-toolbar branch-stock-filter" hidden><label><?= stock_icon('branch') ?><select id="branchFilter" aria-label="Filtrar mis palets por sucursal"><option value="all">Todas las sucursales</option><option value="none">Sin sucursal</option></select></label></div>
 <p id="branchFilterEmpty" class="stock-muted" hidden>No hay palets en esta sucursal.</p>
 <p id="branchStatus" class="library-status" role="status"></p>
 <details id="stockShareDetails" hidden><summary><?= stock_icon('share') ?><span>Enlaces compartidos</span><?= stock_icon('chevron') ?></summary></details>
</section>
<dialog id="branchDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('branch') ?> <span id="branchDialogTitle">Nueva sucursal</span></h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><div id="branchDialogBody" class="branch-dialog-body">
 <form id="branchForm"><details id="branchPointDetails" class="branch-point-details"><summary>Ubicación en el mapa<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></summary><div class="branch-map-frame"><div id="branchPointMap" class="branch-map" aria-label="Marcar ubicación del local"></div><div class="branch-map-controls"><button id="locateBranchPoint" class="library-secondary" type="button" aria-label="Centrar en mi ubicación" title="Centrar en mi ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 2v4m0 12v4M2 12h4m12 0h4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0"/></svg></button><button id="clearBranchPoint" class="library-secondary" type="button" aria-label="Quitar ubicación" title="Quitar ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM9 7l6 6m0-6-6 6"/></svg></button></div></div><p id="branchPointStatus" class="stock-muted" role="status"></p></details><p id="branchFormStatus" class="branch-form-notice" role="status" hidden></p><fieldset id="branchFormFields"><legend class="branch-fields-legend">Datos de la sucursal</legend><label>Nombre de la sucursal<input name="name" maxlength="100" placeholder="Ej.: Carrefour Centro" required></label><label>Dirección<input name="address" maxlength="160" placeholder="Ej.: Av. Colón 1234" required></label><div class="branch-form-row"><label>Localidad<input name="locality" maxlength="100" placeholder="Ej.: Córdoba" required></label><label>Provincia<input name="province" maxlength="80" placeholder="Ej.: Córdoba" required></label></div><label><span>Descripción <small>(opcional)</small></span><textarea name="description" rows="2" maxlength="300" placeholder="Ej.: Depósito, entrada por calle lateral"></textarea></label><input type="hidden" name="latitude"><input type="hidden" name="longitude"><small id="branchAddressSource" class="branch-address-source" hidden>Dirección sugerida con datos de <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>.</small></fieldset></form>
</div><div id="branchDialogActions" class="branch-dialog-footer"><button class="library-primary" id="saveBranchSubmit" type="submit" form="branchForm"><?= stock_icon('check') ?> Guardar sucursal</button></div></dialog>
<dialog id="palletBranchDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('branch') ?> <span id="palletBranchTitle">Sucursal del palet</span></h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><div id="palletBranchBody" class="branch-dialog-body"><div id="palletBranchPreview" class="branch-selected-preview" hidden><div id="palletBranchPreviewInfo"></div><button id="editBranchData" class="library-secondary stock-icon" type="button" aria-label="Editar datos del local" title="Editar datos del local" hidden><?= stock_icon('settings') ?></button><button id="editSelectedBranch" class="library-secondary stock-icon" type="button" aria-label="Cambiar sucursal" title="Cambiar sucursal"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/></svg></button></div><div id="branchPicker" hidden><div class="stock-tabs branch-picker-tabs" role="tablist" aria-label="Elegir sucursal"><button id="branchSearchTab" type="button" role="tab" tabindex="0" aria-selected="true" aria-controls="branchSearchPanel"><?= stock_icon('search') ?> Buscar</button><button id="branchLocationTab" type="button" role="tab" aria-selected="false" aria-controls="branchLocationPanel" tabindex="-1"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg> Mapa</button></div><div id="branchSearchPanel" role="tabpanel" aria-labelledby="branchSearchTab"><form id="palletBranchForm"><label><span>Sucursal <small>(opcional)</small></span><input id="palletBranchSearch" enterkeyhint="search" type="search" autocomplete="off" placeholder="Buscar por nombre o dirección" aria-controls="palletBranchResults"><select id="palletBranchSelect" hidden><option value="">Sin sucursal</option></select></label><div class="branch-shortcuts" role="group" aria-label="Accesos a sucursales"><button type="button" data-branch-scope="all" aria-pressed="true">Todas</button><button type="button" data-branch-scope="favorite" aria-pressed="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/></svg>Favoritos</button><button type="button" data-branch-scope="recent" aria-pressed="false"><?= stock_icon('clock') ?> Recientes</button></div><div id="palletBranchResults" class="branch-search-results" aria-label="Sucursales disponibles"></div><p id="palletBranchEmpty" class="stock-muted" role="status" hidden>No encontramos una sucursal con esos datos.</p><button id="newPalletBranch" class="library-secondary" type="button" aria-expanded="false" aria-controls="palletBranchCreateSlot">Agregar sucursal<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></button><p id="palletBranchStatus" class="library-status" role="status"></p></form><div id="palletBranchCreateSlot" hidden></div></div><div id="branchLocationPanel" role="tabpanel" aria-labelledby="branchLocationTab" hidden><div class="branch-map-frame"><div id="branchLocationMap" class="branch-map" aria-label="Mapa de sucursales"></div><div class="branch-map-controls"><button id="locateBranchUser" class="library-secondary" type="button" aria-label="Centrar en mi ubicación" title="Centrar en mi ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 2v4m0 12v4M2 12h4m12 0h4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0"/></svg></button><button id="clearBranchLocation" class="library-secondary" type="button" aria-label="Quitar ubicación" title="Quitar ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM9 7l6 6m0-6-6 6"/></svg></button></div></div><div class="branch-map-toolbar"><span id="branchLocationStatus" class="stock-muted" role="status"></span></div><div id="branchMapChoice" class="branch-map-choice" hidden><p id="branchMapChoiceLabel"></p><div id="branchMapNearby"></div><button id="addBranchAtPoint" class="library-secondary" type="button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg> Agregar sucursal aquí</button></div></div></div></div><div id="palletBranchConfirmActions" class="branch-dialog-footer"><button id="savePalletBranch" class="library-primary" type="submit" form="palletBranchForm"><?= stock_icon('check') ?> <span>Guardar</span></button></div></dialog>
<dialog id="stockShareDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('share') ?> Compartir palets</h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><form id="stockShareForm"><div class="stock-share-scroll"><div class="stock-tabs share-mode-tabs" role="group" aria-label="Como compartir"><button type="button" data-stock-share-mode="palets" aria-pressed="true"><?= stock_icon('pallet') ?> Palets</button><button type="button" data-stock-share-mode="branch" aria-pressed="false"><?= stock_icon('branch') ?> Sucursal</button></div><p id="stockShareHint" class="stock-muted">Elige los palets que podrá ver quien reciba el enlace.</p><details id="stockShareFilters" class="stock-share-filters"><summary><?= stock_icon('filter') ?><span>Filtros</span><small id="stockShareFilterCount"></small><svg class="library-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="stock-share-filter-fields"><label><?= stock_icon('branch') ?><span>Sucursal</span><select id="stockShareFilterBranch" aria-label="Filtrar palets por sucursal"><option value="all">Todas las sucursales</option></select></label><label id="stockShareTagLabel" hidden><?= stock_icon('tag') ?><span>Etiqueta</span><select id="stockShareFilterTag" aria-label="Filtrar palets por etiqueta"><option value="">Todas las etiquetas</option></select></label></div></details><label class="share-search-label"><?= stock_icon('search') ?><input id="stockShareSearch" type="search" maxlength="160" placeholder="Código, descripción o sucursal" aria-label="Buscar para compartir"></label><div class="share-selection-tools"><span id="stockShareCount" role="status">0 seleccionados</span><button id="stockShareSelectVisible" type="button" class="library-secondary">Seleccionar visibles</button><button id="stockShareClear" type="button" class="library-secondary">Limpiar</button></div><div id="stockShareBranchSelected" hidden><div><strong id="stockShareBranchName"></strong><small id="stockShareBranchAddress"></small></div><button id="stockShareChangeBranch" type="button" class="library-secondary">Cambiar</button></div><div id="stockShareChoices" class="branch-share-choices"></div><div id="stockShareBranchReview" class="library-disclosure" hidden><button id="stockShareBranchToggle" type="button" aria-expanded="false" aria-controls="stockShareBranchPalets"><?= stock_icon('pallet') ?> <span id="stockShareBranchReviewTitle">Palets incluidos</span><small class="share-review-edit">Editar</small><svg class="library-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><p class="stock-muted">Desmarcá los que no quieras compartir.</p><div id="stockShareBranchPalets" class="branch-share-choices"></div></div><p id="stockShareFutureHint" class="stock-muted" hidden>Los nuevos palets de esta sucursal se incluyen automáticamente.</p></div><div class="stock-share-footer"><label>Nombre del enlace <small>(opcional)</small><input name="title" maxlength="100" placeholder="Ej.: Mercadería para revisar"></label><p id="stockShareStatus" class="library-status" role="status"></p><button id="createStockShare" class="library-primary" type="submit" disabled><?= stock_icon('share') ?> Crear enlace</button></div></form><div id="stockShareResult" hidden><p class="library-status" role="status">Enlace listo. Quien lo reciba podrá consultar el contenido sin registrarse.</p><p id="stockShareFeedback" class="library-status" role="status"></p><input id="stockShareURL" readonly aria-label="Enlace público"><div class="branch-toolbar"><button id="copyStockShare" class="library-primary" type="button"><?= stock_icon('share') ?> Compartir enlace</button><a id="openStockShare" class="library-secondary" target="_blank" rel="noopener">Ver enlace</a></div></div></dialog>
<dialog id="stockSharesDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('share') ?> Enlaces compartidos</h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><p class="stock-muted">Estos enlaces permiten ver tus palets sin iniciar sesión.</p><p id="stockSharesStatus" class="library-status" role="status"></p><div id="stockShareList" class="branch-list"></div></dialog>
